107	// Input checks for request bodies and query strings. Each parser returns the clean value or throws a
108	// ValidationError, which the server turns into a 400 reply.
109	
110	export class ValidationError extends Error {
111	  constructor(message) {
112	    super(message)
113	    this.name = 'ValidationError'
114	  }
115	}
