117	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
118	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
119	const MIN_MEMBERS = 2
120	const MAX_MEMBERS = 20
121	const MAX_GROUP_NAME_LENGTH = 100
122	const MAX_DESCRIPTION_LENGTH = 200
123	const CENTS_PER_UNIT = 100
124	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
125	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
126	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
127	
128	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
129	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
130	
131	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
132	
133	export function parseGroupId(v) {
134	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
135	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
136	  }
137	  return v
138	}
139	
140	export function parseGroupName(v) {
141	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
142	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
143	  }
144	  return v
145	}
146	
147	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
148	export function parseMembers(v) {
149	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
150	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
151	  }
152	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
153	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
154	  }
155	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
156	  return [...v]
157	}
158	
159	export function parseDescription(v) {
160	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
161	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
162	  }
163	  return v
164	}
