166	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
167	export function parseAmount(v) {
168	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
169	  // Math.round, not Math.trunc: 4.35 * 100 is 434.99999999999994 in floating point.
170	  const cents = Math.round(v * CENTS_PER_UNIT)
171	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
172	  return cents
173	}
