175	// A name that must belong to one of members; message says which field was wrong.
176	export function parseMember(v, members, message) {
177	  if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
178	  return v
179	}
180	
181	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
182	export function parseSplit(v, members) {
183	  if (v === undefined) return [...members]
184	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
185	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
186	  return [...v]
187	}
188	// HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
