200	// Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
201	// so the 413 reply reaches the client instead of a reset connection.
202	export function readBody(req) {
203	  return new Promise((resolve, reject) => {
204	    const chunks = []
205	    let size = 0
206	    req.on('data', chunk => {
207	      size += chunk.length
208	      if (size <= MAX_BODY_BYTES) chunks.push(chunk)
209	    })
210	    req.on('end', () => {
211	      if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
212	      else resolve(Buffer.concat(chunks).toString('utf8'))
213	    })
214	    req.on('error', reject)
215	  })
216	}
