218	export function parseJsonObject(text) {
219	  let value
220	  try {
221	    value = JSON.parse(text)
222	  } catch {
223	    throw new HttpError(400, 'invalid JSON')
224	  }
225	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
226	    throw new HttpError(400, 'body must be a JSON object')
227	  }
228	  return value
229	}
