231	// Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
232	export function send(res, { status, body }) {
233	  if (body === undefined) {
234	    res.writeHead(status).end()
235	    return
236	  }
237	  const text = JSON.stringify(body)
238	  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
239	  res.end(text)
240	}
