242	export function errorReply(err) {
243	  if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
244	  if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
245	  // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
246	  console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
247	  return { status: 500, body: { error: 'internal error' } }
248	}
